def max_run(s):
    m = s.isna().astype(int)
    if not m.any(): return 0
    runs=[]; c=0
    for v in m:
        if v: c+=1
        else:
            runs.append(c); c=0
    runs.append(c)
    return max(runs)

out = pd.DataFrame({
